**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream f1("studenci.txt"), f2("oceny.txt");
    map<int, string> imiona;
    int id;
    string imie;
    while (f1 >> id >> imie) {
        imiona[id] = imie;
    }

    map<int, int> suma;
    map<int, int> cnt;
    int sid, ocena;
    string przedmiot;
    while (f2 >> sid >> przedmiot >> ocena) {
        suma[sid] += ocena;
        cnt[sid]++;
    }

    cout << fixed << setprecision(2);
    cout << "a) Srednie ocen:" << endl;
    string maxImie;
    double maxSr = 0;
    for (auto &s : imiona) {
        double sr = (double)suma[s.first] / cnt[s.first];
        cout << "   " << s.second << ": " << sr << endl;
        if (sr > maxSr) {
            maxSr = sr;
            maxImie = s.second;
        }
    }

    cout << endl << "b) Najwyzsza srednia: " << maxImie << " (" << maxSr << ")" << endl;

    cout << endl << "c) Liczba przedmiotow:" << endl;
    for (auto &s : imiona) {
        cout << "   " << s.second << ": " << cnt[s.first] << endl;
    }
    return 0;
}
```

Weryfikacja:
- id=1 Ala: 5+4+6 = 15, cnt=3, sr=15/3 = 5.00
- id=2 Bob: 3+5 = 8, cnt=2, sr=8/2 = 4.00
- id=3 Cysia: 5+4+4 = 13, cnt=3, sr=13/3 = 4.333... -> 4.33
- id=4 Darek: 3+4 = 7, cnt=2, sr=7/2 = 3.50
- id=5 Ela: 6+5 = 11, cnt=2, sr=11/2 = 5.50
- Najwyzsza: Ela (5.50)
- Liczba przedmiotow: Ala(3), Bob(2), Cysia(3), Darek(2), Ela(2)
